/// Run the network on an int8 input in the `INPUT` grid.
pub fn forward(input: &Input) -> Output {
    let mut v0 = [[[0i8; 6]; 5]; 8];
    CONV0.forward(input, &mut v0);
    let mut v1 = [[[0i8; 4]; 5]; 8];
    PW1.forward(&v0, &mut v1);
    let mut v2 = [[[0i8; 5]; 2]; 3];
    CONV2.forward(&v1, &mut v2);
    let v3 = FC3.forward(
        v2.as_flattened()
            .as_flattened()
            .first_chunk::<30>()
            .expect("30 values"),
    );
    let v4 = v3.map(|x| apply_lut(x, &TANH4_LUT));
    let v5 = FC5.forward(&v4);
    let v6 = v5.map(|x| apply_lut(x, &SIGMOID6_LUT));
    let v7 = FC7.forward(&v6);
    SOFTMAX8.forward(&v7)
}
